use std::io::{self, Read};

struct P {
    t: Vec<String>,
    i: usize,
    out: Vec<String>,
}

impl P {
    fn peek(&self) -> Option<&str> {
        self.t.get(self.i).map(|s| s.as_str())
    }
    fn expr(&mut self) -> Option<()> {
        self.term()?;
        while let Some(op) = self.peek() {
            if op == "+" || op == "-" {
                let o = op.to_string();
                self.i += 1;
                self.term()?;
                self.out.push(o);
            } else {
                break;
            }
        }
        Some(())
    }
    fn term(&mut self) -> Option<()> {
        self.pow()?;
        while let Some(op) = self.peek() {
            if op == "*" || op == "/" {
                let o = op.to_string();
                self.i += 1;
                self.pow()?;
                self.out.push(o);
            } else {
                break;
            }
        }
        Some(())
    }
    fn pow(&mut self) -> Option<()> {
        self.atom()?;
        if self.peek() == Some("^") {
            self.i += 1;
            self.pow()?;
            self.out.push("^".to_string());
        }
        Some(())
    }
    fn atom(&mut self) -> Option<()> {
        let t = self.peek()?.to_string();
        if t == "(" {
            self.i += 1;
            self.expr()?;
            if self.peek() != Some(")") {
                return None;
            }
            self.i += 1;
            Some(())
        } else if t.chars().all(|c| c.is_ascii_digit()) {
            self.i += 1;
            self.out.push(t);
            Some(())
        } else {
            None
        }
    }
}

fn convert(line: &str) -> Option<String> {
    let mut t = Vec::new();
    let cs: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < cs.len() {
        let c = cs[i];
        if c.is_whitespace() {
            i += 1;
        } else if c.is_ascii_digit() {
            let mut s = String::new();
            while i < cs.len() && cs[i].is_ascii_digit() {
                s.push(cs[i]);
                i += 1;
            }
            t.push(s);
        } else if "+-*/^()".contains(c) {
            t.push(c.to_string());
            i += 1;
        } else {
            return None;
        }
    }
    let mut p = P { t, i: 0, out: vec![] };
    p.expr()?;
    if p.i != p.t.len() {
        return None;
    }
    Some(p.out.join(" "))
}

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    for l in s.lines() {
        if l.trim().is_empty() {
            continue;
        }
        match convert(l) {
            Some(r) => println!("{}", r),
            None => println!("error"),
        }
    }
}

